// 由 tools/site.html 產生：node tools/build.mjs
export default "<!doctype html><html lang=\"zh-Hant\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"robots\" content=\"noindex,nofollow\"><meta name=\"description\" content=\"十八睞讓你美：真人髮片、補髮片，AI 換髮試戴，LINE 一對一諮詢。\"><style>:root{color-scheme:light;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}body{margin:0;font:14px system-ui,sans-serif}img{max-width:100%}[hidden]{display:none!important}</style>\n<title>十八睞讓你美</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Noto+Serif+TC:wght@500;700;900&family=Noto+Sans+TC:wght@400;500;700&display=swap\">\n<style>\n/* Layout: 單欄長頁，hero 左文右髮絲畫布；色票、尺寸表為本主題專屬內容 */\n:root{\n  --bg:#f6f2f3;\n  --surface:#ffffff;\n  --ink:#271c22;\n  --muted:#6e5f67;\n  --line:#e3d8dc;\n  --accent:#8a2e4a;\n  --accent-ink:#ffffff;\n  --soft:#efe4e8;\n  --line-green:#06c755;\n  --f-display:\"Noto Serif TC\",\"Songti TC\",\"PMingLiU\",serif;\n  --f-body:\"Noto Sans TC\",\"PingFang TC\",\"Microsoft JhengHei\",sans-serif;\n}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){\n  --bg:#1a1417;--surface:#241c20;--ink:#f3eaee;--muted:#b9a8b0;--line:#3a2e34;--accent:#e08aa5;--accent-ink:#1a1417;--soft:#2e2328;color-scheme:dark}}\n:root[data-theme=\"dark\"]{\n  --bg:#1a1417;--surface:#241c20;--ink:#f3eaee;--muted:#b9a8b0;--line:#3a2e34;--accent:#e08aa5;--accent-ink:#1a1417;--soft:#2e2328;color-scheme:dark}\n\n*{box-sizing:border-box}\nbody{background:var(--bg);color:var(--ink);font-family:var(--f-body);font-size:16px;line-height:1.75}\n.wrap{max-width:1080px;margin:0 auto;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\nh1,h2,h3{font-family:var(--f-display);text-wrap:balance;margin:0;line-height:1.3}\nh2{font-size:clamp(1.6rem,4vw,2.2rem);font-weight:700}\nh3{font-size:1.15rem;font-weight:700}\np{margin:0}\na{color:inherit}\n.eyebrow{font-size:.8rem;letter-spacing:.2em;color:var(--accent);font-weight:700}\nsection{padding-block:clamp(48px,8vw,88px)}\n.sec-head{display:grid;gap:10px;margin-bottom:32px;max-width:40em}\n.sec-head p{color:var(--muted)}\n.note{display:inline-block;font-size:.75rem;color:var(--muted);border:1px dashed var(--line);border-radius:4px;padding:1px 8px}\n\n/* header */\nheader{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:color-mix(in srgb,var(--bg) 90%,transparent);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:10;background:var(--bg)}\n.nav{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-block:12px}\n.brand{font-family:var(--f-display);font-weight:900;font-size:1.25rem;letter-spacing:.06em;text-decoration:none}\n.nav ul{display:flex;gap:20px;list-style:none;margin:0;padding:0;font-size:.95rem}\n.nav ul a{text-decoration:none;color:var(--muted)}\n.nav ul a:hover{color:var(--ink)}\n@media (max-width:640px){.nav ul{display:none}}\n.btn{display:inline-flex;align-items:center;gap:8px;padding:10px 20px;border-radius:999px;font-weight:700;text-decoration:none;border:1.5px solid var(--accent);font-size:.95rem;cursor:pointer;font-family:inherit}\n.btn.solid{background:var(--accent);color:var(--accent-ink)}\n.btn.ghost{background:transparent;color:var(--accent)}\n.btn:focus-visible,a:focus-visible,button:focus-visible{outline:3px solid var(--accent);outline-offset:3px}\n\n/* hero */\n.hero{display:grid;grid-template-columns:1.1fr 1fr;gap:40px;align-items:center;padding-block:clamp(40px,7vw,80px)}\n.hero h1{font-size:clamp(2.2rem,6.5vw,4rem);font-weight:900;letter-spacing:.02em}\n.hero h1 em{font-style:normal;color:var(--accent)}\n.hero .lead{font-size:1.1rem;color:var(--muted);margin-top:18px;max-width:28em}\n.hero .ctas{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}\n.hero .facts{display:flex;flex-wrap:wrap;gap:24px;margin-top:32px;font-size:.9rem;color:var(--muted)}\n.hero .facts b{display:block;font-family:var(--f-display);font-size:1.4rem;color:var(--ink)}\n.strands{width:100%;aspect-ratio:4/5;max-width:100%;border-radius:200px 200px 16px 16px;background:var(--soft);overflow:hidden}\n.strands canvas{width:100%;height:100%;display:block}\n@media (max-width:780px){.hero{grid-template-columns:1fr}.strands{aspect-ratio:16/10;border-radius:16px;order:-1}}\n\n/* products */\n.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:20px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden;display:flex;flex-direction:column}\n.card .ph{aspect-ratio:4/3;background:var(--soft);display:grid;place-items:center;color:var(--muted);font-size:.8rem}\n.card .ph canvas{width:100%;height:100%;display:block}\n.card .body{padding:18px;display:grid;gap:8px;flex:1;align-content:start}\n.card .body p{color:var(--muted);font-size:.95rem}\n.tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:4px}\n.tag{font-size:.75rem;background:var(--soft);border-radius:999px;padding:2px 10px;color:var(--muted)}\n\n/* colors */\n.swatches{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:16px}\n.sw{display:grid;gap:8px;font-size:.9rem}\n.sw i{display:block;aspect-ratio:1;border-radius:50%;box-shadow:inset 0 -10px 18px rgba(0,0,0,.25),inset 0 8px 14px rgba(255,255,255,.18);border:1px solid var(--line)}\n.sw small{color:var(--muted);font-variant-numeric:tabular-nums}\n\n/* size table */\n.tbl{overflow-x:auto;border:1px solid var(--line);border-radius:12px;background:var(--surface)}\ntable{border-collapse:collapse;width:100%;min-width:540px;font-size:.95rem}\nth,td{text-align:left;padding:12px 16px;border-bottom:1px solid var(--line)}\nth{font-weight:700;background:var(--soft)}\ntr:last-child td{border-bottom:0}\ntd.num{font-variant-numeric:tabular-nums;white-space:nowrap}\n\n/* steps */\n.steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,200px),1fr));gap:20px;counter-reset:s;list-style:none;padding:0;margin:0}\n.steps li{counter-increment:s;display:grid;gap:6px;padding-top:16px;border-top:2px solid var(--accent)}\n.steps li::before{content:\"步驟 \" counter(s);font-size:.8rem;letter-spacing:.15em;color:var(--accent);font-weight:700}\n.steps p{color:var(--muted);font-size:.95rem}\n\n/* faq */\n.faq{display:grid;gap:12px;max-width:760px}\ndetails{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:14px 18px}\nsummary{cursor:pointer;font-weight:700}\ndetails p{color:var(--muted);margin-top:8px}\n\n/* contact */\n.contact{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:clamp(24px,5vw,48px);display:grid;grid-template-columns:1.2fr 1fr;gap:32px;align-items:center}\n@media (max-width:720px){.contact{grid-template-columns:1fr}}\n.lineid{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:12px}\n.lineid code{font-size:1.2rem;font-weight:700;background:var(--soft);padding:6px 14px;border-radius:8px;user-select:all;font-family:var(--f-body)}\n.btn.line{background:var(--line-green);border-color:var(--line-green);color:#fff}\n.info{display:grid;gap:10px;font-size:.95rem}\n.info div{display:grid;grid-template-columns:5em 1fr;gap:8px}\n.info dt{color:var(--muted)}\nfooter{padding-block:32px;color:var(--muted);font-size:.85rem;border-top:1px solid var(--line);margin-top:48px}\n.toast{min-height:1.5em;font-size:.85rem;color:var(--accent)}\n@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\nhtml{scroll-behavior:smooth}\n</style>\n\n</head><body>\n<header>\n  <div class=\"wrap nav\">\n    <a class=\"brand\" href=\"#top\">十八睞讓你美</a>\n    <ul>\n      <li><a href=\"#tryon\">AI 換髮</a></li>\n      <li><a href=\"#products\">商品</a></li>\n      <li><a href=\"#colors\">髮色</a></li>\n      <li><a href=\"#sizes\">尺寸挑選</a></li>\n      <li><a href=\"#order\">訂購流程</a></li>\n      <li><a href=\"#faq\">常見問題</a></li>\n    </ul>\n    <a class=\"btn solid\" href=\"#contact\">LINE 諮詢</a>\n  </div>\n</header>\n\n<main id=\"top\">\n  <div class=\"wrap hero\">\n    <div>\n      <p class=\"eyebrow\">真人髮 ・ 補髮片 ・ 接髮片</p>\n      <h1>一片髮，<br>讓你<em>美</em>回十八歲</h1>\n      <p class=\"lead\">頭頂稀疏、髮量變少、想換個長度，都可以用髮片自然解決。一對一協助選色、選尺寸，戴上就像自己長出來的頭髮。</p>\n      <div class=\"ctas\">\n        <a class=\"btn solid\" href=\"#contact\">加 LINE 免費諮詢</a>\n        <a class=\"btn ghost\" href=\"#tryon\">AI 換髮試戴</a>\n      </div>\n      <div class=\"facts\">\n        <span><b>100%</b>真人髮可燙染</span>\n        <span><b>8 色</b>自然髮色可選</span>\n        <span><b>一對一</b>選色與配戴教學</span>\n      </div>\n    </div>\n    <div class=\"strands\" aria-hidden=\"true\"><canvas id=\"hero-canvas\"></canvas></div>\n  </div>\n\n  <section id=\"tryon\" style=\"padding-top:0\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\">\n        <p class=\"eyebrow\">AI 換髮試戴</p>\n        <h2>先看戴上去的樣子，再決定</h2>\n        <p>上傳正面、頭頂、左右側的照片，AI 幫你找出稀疏的位置，馬上看到補髮片戴上前後的差別。</p>\n      </div>\n\n      <div class=\"tool\">\n        <div class=\"step-h\"><span>步驟 1</span><h3>拍四個角度</h3></div>\n        <div class=\"shots\" id=\"shots\"></div>\n        <div class=\"tool-row\">\n          <button class=\"btn ghost\" type=\"button\" id=\"use-samples\">先用範例照片看看</button>\n        </div>\n        <p class=\"tool-note\">頭頂照請家人從正上方幫拍，或手機舉高往下拍。光線要亮，頭髮照平常的樣子，不要特別撥蓬。至少要有一張。</p>\n        <p class=\"tool-status\"><i></i><span id=\"ai-status\">補髮效果在你的手機上產生。AI 判斷稀疏位置時，照片會傳給 Claude 分析，不會公開。</span></p>\n      </div>\n\n      <div class=\"tool\" id=\"step2\">\n        <div class=\"step-h\"><span>步驟 2</span><h3>看戴上前後</h3></div>\n        <div class=\"tabs\" id=\"tabs\" role=\"tablist\"></div>\n        <div class=\"stage\" id=\"stage\">\n          <canvas id=\"stage-canvas\"></canvas>\n          <span class=\"stage-badge\" id=\"stage-badge\">正面</span>\n          <div class=\"split\" id=\"split\"><b aria-hidden=\"true\">⇆</b></div>\n          <div class=\"stage-empty\" id=\"stage-empty\">先在步驟 1 上傳照片，或按「先用範例照片看看」</div>\n        </div>\n        <div class=\"ctl ctl-split\">\n          <span>戴上後</span>\n          <input type=\"range\" id=\"split-range\" min=\"0\" max=\"100\" value=\"55\" aria-label=\"前後對比位置\">\n          <span>原本</span>\n        </div>\n        <p class=\"hint\" id=\"hint\" role=\"status\"></p>\n        <div class=\"ctl\"><label for=\"size-range\">補髮範圍</label><input type=\"range\" id=\"size-range\" min=\"0\" max=\"100\" value=\"45\"></div>\n        <div class=\"ctl\"><label for=\"density-range\">濃密度</label><input type=\"range\" id=\"density-range\" min=\"0\" max=\"100\" value=\"75\"></div>\n        <div class=\"ctl ctl-color\"><span>髮片顏色</span>\n          <div class=\"chips\" id=\"chips\"></div>\n        </div>\n        <div class=\"checks\">\n          <label><input type=\"checkbox\" id=\"show-region\" checked> 顯示補髮範圍</label>\n          <span class=\"muted\">拖曳照片可移動補髮位置</span>\n        </div>\n        <label class=\"checks\"><input type=\"checkbox\" id=\"mosaic\" checked> 下載的圖只留頭髮，臉和背景打馬賽克</label>\n        <div class=\"tool-row\">\n          <button class=\"btn solid\" type=\"button\" id=\"generate\" hidden>AI 生成逼真效果</button>\n          <button class=\"btn ghost\" type=\"button\" id=\"download\" hidden>下載這個角度的前後圖</button>\n          <button class=\"btn ghost\" type=\"button\" id=\"reanalyze\" hidden>請 AI 重新判斷</button>\n          <a class=\"btn solid\" href=\"#contact\">喜歡這個效果，傳給我們估價</a>\n        </div>\n        <p class=\"tool-note\" id=\"ai-mode\"></p>\n        <p class=\"toast\" id=\"tool-toast\" role=\"status\"></p>\n        <p class=\"tool-note\">試戴畫面是模擬效果，實際成品依髮片款式、髮色與配戴方式會有差異。</p>\n      </div>\n    </div>\n  </section>\n\n<style>\n[hidden]{display:none!important}\n.tool{background:var(--surface);border:1px solid var(--line);border-radius:20px;padding:clamp(16px,4vw,28px);display:grid;gap:16px;margin-bottom:20px}\n.step-h{display:flex;align-items:baseline;gap:12px}\n.step-h span{color:var(--accent);font-weight:700;font-size:.9rem;letter-spacing:.1em}\n.step-h h3{font-size:clamp(1.3rem,3.5vw,1.6rem)}\n.shots{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}\n@media (max-width:720px){.shots{grid-template-columns:repeat(2,minmax(0,1fr))}}\n.shot{position:relative;aspect-ratio:4/5;max-width:100%;border:1.5px dashed var(--line);border-radius:14px;background:var(--soft);display:grid;place-items:center;align-content:center;gap:6px;text-align:center;cursor:pointer;overflow:hidden;color:var(--muted);font-size:.85rem;padding:8px}\n.shot:hover{border-color:var(--accent)}\n.shot:focus-within{outline:3px solid var(--accent);outline-offset:2px}\n.shot input{position:absolute;inset:0;opacity:0;cursor:pointer}\n.shot svg{width:30px;height:30px;stroke:var(--muted)}\n.shot b{background:var(--surface);color:var(--ink);border-radius:999px;padding:2px 12px;font-size:.9rem}\n.shot img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;pointer-events:none}\n.shot.filled{border-style:solid;border-color:var(--accent)}\n.shot.filled b{position:absolute;top:8px;left:8px;z-index:1}\n.shot.filled .sub,.shot.filled svg{display:none}\n.tool-row{display:flex;flex-wrap:wrap;gap:10px}\n.tool-note{color:var(--muted);font-size:.9rem}\n.tool-status{display:flex;gap:8px;align-items:baseline;font-size:.88rem;color:var(--muted)}\n.tool-status i{flex:none;width:9px;height:9px;border-radius:50%;background:#3d7a5a;transform:translateY(-1px)}\n.tabs{display:flex;flex-wrap:wrap;gap:8px}\n.tabs button{font:inherit;font-weight:700;padding:6px 18px;border-radius:999px;border:1.5px solid var(--line);background:var(--surface);color:var(--ink);cursor:pointer}\n.tabs button[aria-selected=\"true\"]{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}\n.tabs button:disabled{opacity:.4;cursor:default}\n.stage{position:relative;border-radius:14px;overflow:hidden;background:var(--soft);touch-action:none;user-select:none;max-width:560px;width:100%;justify-self:center}\n.stage canvas{display:block;width:100%;height:auto;cursor:grab}\n.stage-badge{position:absolute;top:10px;left:10px;background:rgba(30,22,26,.78);color:#fff;border-radius:999px;padding:2px 12px;font-size:.85rem}\n.split{position:absolute;top:0;bottom:0;width:2px;background:#fff;box-shadow:0 0 0 1px rgba(0,0,0,.12);transform:translateX(-1px);pointer-events:none}\n.split b{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:34px;height:34px;border-radius:50%;background:#fff;color:#8a2e4a;display:grid;place-items:center;font-size:1rem;box-shadow:0 2px 6px rgba(0,0,0,.2)}\n.stage-empty{position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:24px;color:var(--muted);min-height:280px;position:relative}\n.ctl{display:grid;grid-template-columns:6em minmax(0,1fr);gap:12px;align-items:center;color:var(--muted)}\n.ctl-split{grid-template-columns:auto minmax(0,1fr) auto}\n.ctl input[type=range]{width:100%;accent-color:var(--accent)}\n.ctl-color{align-items:start}\n.chips{display:flex;flex-wrap:wrap;gap:8px}\n.chips button{font:inherit;font-size:.85rem;display:inline-flex;align-items:center;gap:6px;padding:4px 12px 4px 6px;border-radius:999px;border:1.5px solid var(--line);background:var(--surface);color:var(--ink);cursor:pointer}\n.chips button i{width:18px;height:18px;border-radius:50%;border:1px solid var(--line)}\n.chips button[aria-pressed=\"true\"]{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}\n.hint{color:#9a5b1e;font-size:1rem;min-height:1.5em}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]) .hint{color:#e0a96b}}\n:root[data-theme=\"dark\"] .hint{color:#e0a96b}\n.checks{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px;align-items:center}\n.checks label,label.checks{display:inline-flex;gap:8px;align-items:center;cursor:pointer;justify-content:flex-start}\n.checks input{width:20px;height:20px;accent-color:var(--accent)}\n.muted{color:var(--muted);font-size:.9rem}\n</style>\n\n<script>\nconst SAMPLES={\"front\": \"data:image/jpeg;base64,\", \"top\": \"data:image/jpeg;base64,\", \"left\": \"data:image/jpeg;base64,\", \"right\": \"data:image/jpeg;base64,\"};\n(function(){\n  const ANGLES = [\n    {k:'front', name:'正面', sub:'臉朝前，平視鏡頭', region:{cx:.5,cy:.17,rx:.23,ry:.11}, whorl:[0,-1.6],\n     sample:'前額到頭頂明顯稀疏，已框出補髮範圍。可以拖曳照片微調位置，再用「濃密度」調整髮量。'},\n    {k:'top', name:'頭頂', sub:'從正上方往下拍', region:{cx:.5,cy:.45,rx:.25,ry:.27}, whorl:[0,-.75],\n     sample:'頭頂中央大面積稀疏，適合 13 × 15 cm 底座。可以把「補髮範圍」往右調，看整體加密的效果。'},\n    {k:'left', name:'左側', sub:'臉朝左，拍左邊', region:{cx:.5,cy:.2,rx:.2,ry:.11}, whorl:[1.1,-1.2],\n     sample:'側面可以看到前額上方較稀疏，戴上後側面輪廓會比較飽滿。'},\n    {k:'right', name:'右側', sub:'臉朝右，拍右邊', region:{cx:.5,cy:.19,rx:.2,ry:.11}, whorl:[-1.1,-1.2],\n     sample:'右側前額上方稀疏，補髮後髮際線會比較自然。'}\n  ];\n  const COLORS = [\n    {k:'auto', name:'自動比色'},\n    {k:'#141011', name:'自然黑'},\n    {k:'#2a1d18', name:'深棕黑'},\n    {k:'#3b2a22', name:'自然深棕'},\n    {k:'#5a3b2a', name:'巧克力棕'},\n    {k:'#7a4f35', name:'栗子棕'},\n    {k:'mix', name:'黑白混色'}\n  ];\n  const MAX = 900;\n  const $ = id => document.getElementById(id);\n  const S = {photos:{}, cur:null, color:'auto', drag:null, server:false, serverState:'none', busy:false};\n  const cv = $('stage-canvas'), ctx = cv.getContext('2d');\n  let sampleApi = null, downloadsApi = null;\n\n  // ---- step 1 tiles\n  const cam = '<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke-width=\"1.6\"><path d=\"M4 8h3l2-2.5h6L17 8h3v11H4z\"/><circle cx=\"12\" cy=\"13\" r=\"3.5\"/></svg>';\n  ANGLES.forEach(a => {\n    const el = document.createElement('label');\n    el.className = 'shot'; el.id = 'shot-' + a.k;\n    el.innerHTML = cam + '<b>' + a.name + '</b><span class=\"sub\">' + a.sub + '</span><input type=\"file\" accept=\"image/*\" id=\"file-' + a.k + '\" aria-label=\"上傳' + a.name + '照片\">';\n    el.querySelector('input').addEventListener('change', e => {\n      const f = e.target.files && e.target.files[0];\n      if (!f) return;\n      const url = URL.createObjectURL(f);\n      loadPhoto(a.k, url, false).then(() => { select(a.k); analyze(a.k); });\n    });\n    $('shots').appendChild(el);\n    const t = document.createElement('button');\n    t.type = 'button'; t.role = 'tab'; t.textContent = a.name; t.dataset.k = a.k; t.disabled = true;\n    t.addEventListener('click', () => select(a.k));\n    $('tabs').appendChild(t);\n  });\n  COLORS.forEach(c => {\n    const b = document.createElement('button');\n    b.type = 'button'; b.dataset.k = c.k;\n    const bg = c.k === 'auto' ? 'conic-gradient(#141011,#7a4f35,#b88a5e,#141011)' : c.k === 'mix' ? 'linear-gradient(135deg,#2a1d18 50%,#9a9590 50%)' : c.k;\n    b.innerHTML = '<i style=\"background:' + bg + '\"></i>' + c.name;\n    b.setAttribute('aria-pressed', c.k === S.color);\n    b.addEventListener('click', () => { S.color = c.k; [...$('chips').children].forEach(x => x.setAttribute('aria-pressed', x.dataset.k === c.k)); render(); });\n    $('chips').appendChild(b);\n  });\n\n  function loadPhoto(k, src, isSample){\n    return new Promise((res, rej) => {\n      const img = new Image();\n      img.onload = () => {\n        const sc = Math.min(1, MAX / Math.max(img.naturalWidth, img.naturalHeight));\n        const w = Math.round(img.naturalWidth * sc), h = Math.round(img.naturalHeight * sc);\n        const c = document.createElement('canvas'); c.width = w; c.height = h;\n        c.getContext('2d').drawImage(img, 0, 0, w, h);\n        const a = ANGLES.find(x => x.k === k);\n        S.photos[k] = {before:c, fg:fgMask(c), w, h, region:{...a.region}, hint: isSample ? a.sample : '已先框出常見的稀疏位置，可以拖曳照片調整。', cache:null, colorCache:null};\n        const tile = $('shot-' + k);\n        tile.classList.add('filled');\n        let im = tile.querySelector('img');\n        if (!im) { im = document.createElement('img'); im.alt = ''; tile.prepend(im); }\n        im.src = src;\n        [...$('tabs').children].forEach(t => { if (t.dataset.k === k) t.disabled = false; });\n        res();\n      };\n      img.onerror = () => { toast('這張照片讀不出來，請換一張 JPG 或 PNG。'); rej(); };\n      img.src = src;\n    });\n  }\n\n  $('use-samples').addEventListener('click', async () => {\n    for (const a of ANGLES) await loadPhoto(a.k, SAMPLES[a.k], true);\n    select('front');\n    $('step2').scrollIntoView({behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block:'start'});\n  });\n\n  function select(k){\n    S.cur = k;\n    [...$('tabs').children].forEach(t => t.setAttribute('aria-selected', t.dataset.k === k));\n    $('stage-badge').textContent = ANGLES.find(a => a.k === k).name;\n    render();\n  }\n\n  // ---- hair synthesis\n  // 找出背景（從照片邊緣往內、顏色接近邊緣的區域），補髮只畫在頭上，不畫到背景\n  function fgMask(c){\n    const sw = 180, sh = Math.max(1, Math.round(c.height * sw / c.width));\n    const s = document.createElement('canvas'); s.width = sw; s.height = sh;\n    const sg = s.getContext('2d'); sg.drawImage(c, 0, 0, sw, sh);\n    const im = sg.getImageData(0, 0, sw, sh), d = im.data;\n    const border = [];\n    for (let x = 0; x < sw; x++) border.push(x, x + (sh - 1) * sw);\n    for (let y = 0; y < sh; y++) border.push(y * sw, y * sw + sw - 1);\n    const med = ch => { const v = border.map(i => d[i * 4 + ch]).sort((a, b) => a - b); return v[v.length >> 1]; };\n    const ref = [med(0), med(1), med(2)];\n    const dist = (i, r) => Math.hypot(d[i*4] - r[0], d[i*4+1] - r[1], d[i*4+2] - r[2]);\n    const chroma = i => Math.max(d[i*4], d[i*4+1], d[i*4+2]) - Math.min(d[i*4], d[i*4+1], d[i*4+2]);\n    const refChroma = Math.max(...ref) - Math.min(...ref);\n    const bg = new Uint8Array(sw * sh), q = [];\n    border.forEach(i => { if (!bg[i] && dist(i, ref) < 42) { bg[i] = 1; q.push(i); } });\n    while (q.length) {\n      const i = q.pop(), x = i % sw, y = (i / sw) | 0;\n      const pc = [d[i*4], d[i*4+1], d[i*4+2]];\n      for (const j of [x > 0 ? i - 1 : -1, x < sw - 1 ? i + 1 : -1, y > 0 ? i - sw : -1, y < sh - 1 ? i + sw : -1]) {\n        if (j < 0 || bg[j]) continue;\n        if (dist(j, pc) < 12 && dist(j, ref) < 44 && chroma(j) < refChroma + 10) { bg[j] = 1; q.push(j); }\n      }\n    }\n    for (let i = 0; i < sw * sh; i++) { d[i*4] = d[i*4+1] = d[i*4+2] = 0; d[i*4+3] = bg[i] ? 0 : 255; }\n    sg.putImageData(im, 0, 0);\n    const m = document.createElement('canvas'); m.width = c.width; m.height = c.height;\n    const mg = m.getContext('2d'); mg.filter = 'blur(' + Math.max(1, c.width / 300) + 'px)';\n    mg.drawImage(s, 0, 0, c.width, c.height);\n    return m;\n  }\n  function rnd(seed){ let s = seed % 2147483647 || 1; return () => (s = s * 16807 % 2147483647) / 2147483647; }\n  const sizeScale = () => .55 + $('size-range').value / 100 * 1.1;\n  const density = () => $('density-range').value / 100;\n\n  function regionPx(p, extra = 1){\n    const sc = sizeScale() * extra;\n    return {cx:p.region.cx * p.w, cy:p.region.cy * p.h, rx:p.region.rx * p.w * sc, ry:p.region.ry * p.h * sc};\n  }\n\n  function detectColor(p){\n    const r = regionPx(p);\n    const key = [r.cx, r.cy, r.rx, r.ry].map(Math.round).join();\n    if (p.colorCache && p.colorCache.key === key) return p.colorCache.rgb;\n    const d = p.before.getContext('2d').getImageData(0, 0, p.w, p.h).data;\n    const px = [];\n    for (let y = 0; y < p.h; y += 3) for (let x = 0; x < p.w; x += 3) {\n      const e = ((x - r.cx) / r.rx) ** 2 + ((y - r.cy) / r.ry) ** 2;\n      if (e < 1 || e > 4.5) continue;\n      const i = (y * p.w + x) * 4;\n      px.push([.3 * d[i] + .59 * d[i+1] + .11 * d[i+2], d[i], d[i+1], d[i+2]]);\n    }\n    let rgb = [42, 29, 24];\n    if (px.length > 40) {\n      px.sort((a, b) => a[0] - b[0]);\n      const n = Math.max(10, Math.floor(px.length * .18));\n      rgb = [0, 0, 0];\n      for (let i = 0; i < n; i++) { rgb[0] += px[i][1]; rgb[1] += px[i][2]; rgb[2] += px[i][3]; }\n      rgb = rgb.map(v => Math.round(v / n));\n    }\n    p.colorCache = {key, rgb};\n    return rgb;\n  }\n  const hex2rgb = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16));\n\n  function hairLayer(p){\n    const r = regionPx(p), d = density();\n    const key = [S.cur, r.cx, r.cy, r.rx, r.ry, d, S.color].map(v => typeof v === 'number' ? Math.round(v * 100) : v).join('|');\n    if (p.cache && p.cache.key === key) return p.cache.c;\n    const c = document.createElement('canvas'); c.width = p.w; c.height = p.h;\n    const g = c.getContext('2d');\n    const palette = S.color === 'auto' ? [detectColor(p)] : S.color === 'mix' ? [[42,29,24],[42,29,24],[48,36,30],[154,149,144]] : [hex2rgb(S.color)];\n    const base = palette[0];\n    const a = ANGLES.find(x => x.k === S.cur);\n    const W = [r.cx + a.whorl[0] * r.rx, r.cy + a.whorl[1] * r.ry];\n    const k = p.w / 700;\n\n    // scalp cover\n    g.save(); g.translate(r.cx, r.cy); g.scale(r.rx, r.ry);\n    const bg = g.createRadialGradient(0, 0, 0, 0, 0, 1);\n    bg.addColorStop(0, `rgba(${base},${.5 * d})`); bg.addColorStop(.65, `rgba(${base},${.38 * d})`); bg.addColorStop(1, `rgba(${base},0)`);\n    g.fillStyle = bg; g.beginPath(); g.arc(0, 0, 1, 0, Math.PI * 2); g.fill(); g.restore();\n\n    // strands\n    const R = rnd(Math.round(r.cx * 7 + r.cy * 13) + 11);\n    const n = Math.min(9000, Math.round(d * Math.PI * r.rx * r.ry / (12 * k * k)));\n    const L0 = .55 * Math.max(r.rx, r.ry);\n    g.lineCap = 'round';\n    for (let i = 0; i < n; i++) {\n      const t = R() * Math.PI * 2, u = Math.sqrt(R());\n      const x = r.cx + Math.cos(t) * u * r.rx, y = r.cy + Math.sin(t) * u * r.ry;\n      let dx = x - W[0], dy = y - W[1];\n      const m = Math.hypot(dx, dy) || 1; dx /= m; dy /= m;\n      const ang = Math.atan2(dy, dx) + (R() - .5) * .5;\n      const L = L0 * (.45 + R() * .75);\n      const ex = Math.cos(ang) * L, ey = Math.sin(ang) * L;\n      const bend = (R() - .5) * .35 * L;\n      const sx = x - ex * .5, sy = y - ey * .5;\n      const col = palette[Math.floor(R() * palette.length)];\n      const hi = R() < .07 ? 1.7 : .7 + R() * .55;\n      g.strokeStyle = `rgba(${col.map(v => Math.min(255, Math.round(v * hi + (hi > 1.5 ? 18 : 0)))).join()},${.5 + R() * .45})`;\n      g.lineWidth = (.55 + R() * .9) * k;\n      g.beginPath(); g.moveTo(sx, sy);\n      g.quadraticCurveTo(sx + ex * .5 - ey / L * bend, sy + ey * .5 + ex / L * bend, sx + ex, sy + ey);\n      g.stroke();\n    }\n\n    // feathered edge, only on the head\n    g.globalCompositeOperation = 'destination-in';\n    if (p.fg) g.drawImage(p.fg, 0, 0);\n    g.save(); g.translate(r.cx, r.cy); g.scale(r.rx, r.ry);\n    const mg = g.createRadialGradient(0, 0, 0, 0, 0, 1.08);\n    mg.addColorStop(0, 'rgba(0,0,0,1)'); mg.addColorStop(.62, 'rgba(0,0,0,1)'); mg.addColorStop(1, 'rgba(0,0,0,0)');\n    g.fillStyle = mg; g.fillRect(-2, -2, 4, 4); g.restore();\n    p.cache = {key, c};\n    return c;\n  }\n\n  function render(){\n    const p = S.photos[S.cur];\n    $('stage-empty').hidden = !!p; cv.hidden = !p; $('split').hidden = !p; $('stage-badge').hidden = !p;\n    $('download').hidden = !p || !(downloadsApi || S.server);\n    $('generate').hidden = !p || !S.server;\n    $('generate').disabled = S.busy;\n    $('ai-mode').textContent = {\n      none: '這是預覽版，只有快速模擬。「AI 生成逼真效果」按鈕只會出現在正式網站（vercel.app 網址）。',\n      unconfigured: '正式網站還沒讀到 Gemini API key：請到 Vercel 的 Settings → Environment Variables 確認 GEMINI_API_KEY，再到 Deployments 按 Redeploy。',\n      locked: '請用含存取碼的連結（網址後面加 /?k=存取碼）重新打開，才能使用 AI 生成。',\n      ready: ''\n    }[S.serverState];\n    $('reanalyze').hidden = !p || !sampleApi;\n    if (!p) { $('hint').textContent = ''; return; }\n    if (cv.width !== p.w || cv.height !== p.h) { cv.width = p.w; cv.height = p.h; }\n    const split = $('split-range').value / 100, sx = split * p.w;\n    ctx.drawImage(p.before, 0, 0);\n    ctx.save(); ctx.beginPath(); ctx.rect(0, 0, sx, p.h); ctx.clip();\n    if (p.ai) ctx.drawImage(p.ai.canvas, 0, 0, p.w, p.h); else ctx.drawImage(hairLayer(p), 0, 0);\n    ctx.restore();\n    if ($('show-region').checked) {\n      const r = regionPx(p);\n      ctx.save(); ctx.setLineDash([8 * p.w / 700, 6 * p.w / 700]); ctx.lineWidth = 2 * p.w / 700;\n      ctx.strokeStyle = 'rgba(255,255,255,.9)'; ctx.beginPath(); ctx.ellipse(r.cx, r.cy, r.rx, r.ry, 0, 0, Math.PI * 2); ctx.stroke(); ctx.restore();\n    }\n    $('split').style.left = (split * 100) + '%';\n    $('hint').textContent = p.ai ? (p.ai.key === aiKey(p) ? 'AI 已生成戴上髮片的效果。左右拖曳中間的線比較前後。' : '範圍或顏色已調整，按「AI 生成逼真效果」重新產生。') : S.server ? '現在是快速預覽。框好補髮範圍後，按下方「AI 生成逼真效果」看真實照片效果。' : p.hint;\n  }\n  function aiKey(p){ const r = regionPx(p); return [S.cur, r.cx, r.cy, r.rx, r.ry, density(), S.color].map(v => typeof v === 'number' ? Math.round(v * 100) : v).join('|'); }\n\n  // ---- Gemini（正式網站才有，經由 /api/tryon，API key 在伺服器端）\n  async function generate(){\n    const p = S.photos[S.cur]; if (!p || S.busy) return;\n    const k = S.cur, key = aiKey(p), r = regionPx(p);\n    const mask = document.createElement('canvas'); mask.width = p.w; mask.height = p.h;\n    const mg = mask.getContext('2d'); mg.fillStyle = '#000'; mg.fillRect(0, 0, p.w, p.h);\n    mg.fillStyle = '#fff'; mg.beginPath(); mg.ellipse(r.cx, r.cy, r.rx, r.ry, 0, 0, Math.PI * 2); mg.fill();\n    const c = COLORS.find(x => x.k === S.color);\n    S.busy = true; $('generate').textContent = 'AI 生成中，約 10–30 秒…'; render();\n    try {\n      const resp = await fetch('/api/tryon', {method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify({\n        image: p.before.toDataURL('image/jpeg', .9), mask: mask.toDataURL('image/png'),\n        angle: ANGLES.find(a => a.k === k).name, color: S.color === 'auto' ? '' : c.name, density: density()})});\n      const j = await resp.json().catch(() => ({}));\n      if (!resp.ok || !j.image) throw j.error || 'gemini_error';\n      const img = new Image();\n      await new Promise((ok, bad) => { img.onload = ok; img.onerror = bad; img.src = j.image; });\n      const out = document.createElement('canvas'); out.width = p.w; out.height = p.h;\n      out.getContext('2d').drawImage(img, 0, 0, p.w, p.h);\n      p.ai = {canvas: out, key};\n      if (+$('split-range').value < 30) $('split-range').value = 55;\n      toast('');\n    } catch (e) {\n      toast({not_configured:'網站還沒設定 Gemini API key。', rate_limited:'試用次數太多了，請一小時後再試。', gemini_quota:'Gemini 額度用完了，請稍後再試。', gemini_billing:'Gemini 帳號還沒開啟付費（Billing），生圖功能需要開啟後才能使用。', no_image:'AI 這次沒有產生照片，換個範圍再試一次。'}[e] || 'AI 生成失敗，請再試一次。');\n    }\n    S.busy = false; $('generate').textContent = 'AI 生成逼真效果';\n    if (S.cur === k) render();\n  }\n  $('generate').addEventListener('click', generate);\n  ['size-range', 'density-range', 'split-range', 'show-region'].forEach(id => $(id).addEventListener('input', render));\n\n  // ---- drag: split line or region\n  function toImg(e){ const b = cv.getBoundingClientRect(); return {x:(e.clientX - b.left) / b.width, y:(e.clientY - b.top) / b.height, bw:b.width}; }\n  cv.addEventListener('pointerdown', e => {\n    const p = S.photos[S.cur]; if (!p) return;\n    const q = toImg(e), split = $('split-range').value / 100;\n    S.drag = Math.abs(q.x - split) * q.bw < 22 ? {mode:'split'} : {mode:'move', ox:q.x - p.region.cx, oy:q.y - p.region.cy};\n    cv.setPointerCapture(e.pointerId); cv.style.cursor = 'grabbing';\n  });\n  cv.addEventListener('pointermove', e => {\n    if (!S.drag) return;\n    const p = S.photos[S.cur], q = toImg(e);\n    if (S.drag.mode === 'split') $('split-range').value = Math.round(Math.max(0, Math.min(1, q.x)) * 100);\n    else { p.region.cx = Math.max(0, Math.min(1, q.x - S.drag.ox)); p.region.cy = Math.max(0, Math.min(1, q.y - S.drag.oy)); }\n    render();\n  });\n  const end = () => { S.drag = null; cv.style.cursor = ''; };\n  cv.addEventListener('pointerup', end); cv.addEventListener('pointercancel', end);\n\n  // ---- AI: find the thin area\n  async function analyze(k){\n    const p = S.photos[k]; if (!p || !sampleApi) return;\n    const lim = await sampleApi.limits().catch(() => null);\n    if (!lim || !lim.images) return;\n    const name = ANGLES.find(a => a.k === k).name;\n    p.hint = 'AI 正在判斷稀疏位置…'; if (S.cur === k) render();\n    try {\n      const blob = await new Promise(r => p.before.toBlob(r, 'image/jpeg', .85));\n      const out = await sampleApi.json(\n        '你是假髮與補髮片的顧問。附圖是客人「' + name + '」角度的頭髮照片。請找出頭髮最稀疏、最需要補髮片的區域，用一個橢圓框住。' +\n        '只回傳 JSON：{\"thin\":\"none|mild|moderate|severe\",\"cx\":0到1,\"cy\":0到1,\"rx\":0到0.5,\"ry\":0到0.5,\"hint\":\"一到兩句繁體中文建議，口語、親切，可提到建議的底座尺寸（6×9、10×12、13×15 cm）\"}。' +\n        'cx、cy 是橢圓中心相對圖片寬高的位置（左上為 0），rx、ry 是半徑相對圖片寬高的比例。如果這個角度看不到明顯稀疏，thin 填 none，框住頭頂頭髮區域，hint 建議客人把「補髮範圍」往右調看整體加密效果。',\n        {images:[blob], modelTier:'default'});\n      const cl = (v, lo, hi, dflt) => typeof v === 'number' && isFinite(v) ? Math.max(lo, Math.min(hi, v)) : dflt;\n      const sc = sizeScale();\n      p.region = {cx:cl(out.cx, 0, 1, p.region.cx), cy:cl(out.cy, 0, 1, p.region.cy), rx:cl(out.rx, .05, .5, p.region.rx * sc) / sc, ry:cl(out.ry, .05, .5, p.region.ry * sc) / sc};\n      p.hint = typeof out.hint === 'string' && out.hint ? out.hint : '已框出稀疏位置，可以拖曳照片微調。';\n    } catch (e) {\n      p.hint = e && e.code === 'rate_limited' ? 'AI 現在比較忙，先用預設範圍，等一下可以按「請 AI 重新判斷」。' : '已先框出常見的稀疏位置，可以拖曳照片調整。';\n    }\n    if (S.cur === k) render();\n  }\n  $('reanalyze').addEventListener('click', () => analyze(S.cur));\n\n  // ---- download before/after\n  function composed(p, withHair, mosaic){\n    const c = document.createElement('canvas'); c.width = p.w; c.height = p.h;\n    const g = c.getContext('2d');\n    g.drawImage(p.before, 0, 0);\n    if (withHair) { if (p.ai) g.drawImage(p.ai.canvas, 0, 0, p.w, p.h); else g.drawImage(hairLayer(p), 0, 0); }\n    if (!mosaic) return c;\n    const bs = Math.max(8, Math.round(p.w / 36));\n    const s = document.createElement('canvas'); s.width = Math.ceil(p.w / bs); s.height = Math.ceil(p.h / bs);\n    s.getContext('2d').drawImage(c, 0, 0, s.width, s.height);\n    const m = document.createElement('canvas'); m.width = p.w; m.height = p.h;\n    const mg = m.getContext('2d'); mg.imageSmoothingEnabled = false;\n    mg.drawImage(s, 0, 0, p.w, p.h);\n    const r = regionPx(p, 1.25);\n    mg.save(); mg.beginPath(); mg.ellipse(r.cx, r.cy, r.rx, r.ry, 0, 0, Math.PI * 2); mg.clip(); mg.drawImage(c, 0, 0); mg.restore();\n    return m;\n  }\n  $('download').addEventListener('click', async () => {\n    const p = S.photos[S.cur]; if (!p || !(downloadsApi || S.server)) return;\n    const mos = $('mosaic').checked, gap = Math.round(p.w * .03), foot = Math.round(p.w * .08);\n    const out = document.createElement('canvas'); out.width = p.w * 2 + gap; out.height = p.h + foot;\n    const g = out.getContext('2d');\n    g.fillStyle = '#ffffff'; g.fillRect(0, 0, out.width, out.height);\n    g.drawImage(composed(p, false, mos), 0, 0);\n    g.drawImage(composed(p, true, mos), p.w + gap, 0);\n    const fs = Math.round(p.w * .045);\n    g.font = `700 ${fs}px \"Noto Sans TC\", sans-serif`;\n    [['原本', 0], ['戴上後', p.w + gap]].forEach(([t, x]) => {\n      const tw = g.measureText(t).width;\n      g.fillStyle = 'rgba(30,22,26,.78)'; g.fillRect(x + fs * .6, fs * .6, tw + fs, fs * 1.6);\n      g.fillStyle = '#fff'; g.fillText(t, x + fs * 1.1, fs * 1.75);\n    });\n    g.fillStyle = '#8a2e4a'; g.font = `700 ${Math.round(fs * .9)}px \"Noto Serif TC\", serif`;\n    g.fillText('十八睞讓你美 ・ AI 換髮試戴（模擬效果）', fs * .6, p.h + foot * .65);\n    const blob = await new Promise(r => out.toBlob(r, 'image/png'));\n    const name = ANGLES.find(a => a.k === S.cur).name;\n    const filename = '十八睞讓你美-' + name + '-戴上前後.png';\n    if (!downloadsApi) {\n      const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = filename;\n      document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(a.href), 5000);\n      return;\n    }\n    try { await downloadsApi.save({filename, data:blob}); toast('已存下前後圖'); }\n    catch (e) { toast(e && e.code === 'declined' ? '已取消下載' : '這裡無法下載圖片，可以直接截圖。'); }\n  });\n\n  function toast(t){ $('tool-toast').textContent = t; }\n  render();\n\n  if (location.protocol.startsWith('http')) {\n    fetch('/api/tryon').then(r => r.status === 403 ? {locked:true} : r.ok ? r.json() : null).then(j => { S.server = !!(j && j.ok && j.configured); S.serverState = !j ? 'none' : j.locked ? 'locked' : S.server ? 'ready' : 'unconfigured'; render(); }).catch(() => {});\n  }\n  if (window.claude && window.claude.use) {\n    window.claude.use('sample').then(s => { sampleApi = s; render(); }).catch(() => {});\n    window.claude.use('downloads').then(d => { downloadsApi = d; render(); }).catch(() => {});\n  }\n})();\n</script>\n\n  <section id=\"products\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\">\n        <p class=\"eyebrow\">商品系列</p>\n        <h2>依你的需求，選一種髮片</h2>\n        <p>以下為商品分類示意，實際款式、照片與價格請提供後替換。<span class=\"note\">示意內容</span></p>\n      </div>\n      <div class=\"grid\">\n        <article class=\"card\">\n          <div class=\"ph\"><canvas data-hair=\"top\" data-color=\"#3b2a22\"></canvas></div>\n          <div class=\"body\">\n            <h3>頭頂補髮片</h3>\n            <p>針對頭頂、髮旋稀疏設計，透氣網底加隱形卡扣，日常配戴不悶熱。</p>\n            <div class=\"tags\"><span class=\"tag\">網底</span><span class=\"tag\">卡扣固定</span><span class=\"tag\">價格請洽詢</span></div>\n          </div>\n        </article>\n        <article class=\"card\">\n          <div class=\"ph\"><canvas data-hair=\"bang\" data-color=\"#1f1a19\"></canvas></div>\n          <div class=\"body\">\n            <h3>瀏海髮片</h3>\n            <p>空氣瀏海、八字瀏海、齊瀏海，三秒換髮型，也能遮住髮際線。</p>\n            <div class=\"tags\"><span class=\"tag\">空氣瀏海</span><span class=\"tag\">八字瀏海</span><span class=\"tag\">價格請洽詢</span></div>\n          </div>\n        </article>\n        <article class=\"card\">\n          <div class=\"ph\"><canvas data-hair=\"long\" data-color=\"#6b4630\"></canvas></div>\n          <div class=\"body\">\n            <h3>接髮片・增量片</h3>\n            <p>一片式或多片式，增加長度與髮量，可依原生髮色混色。</p>\n            <div class=\"tags\"><span class=\"tag\">40–60 cm</span><span class=\"tag\">可燙染</span><span class=\"tag\">價格請洽詢</span></div>\n          </div>\n        </article>\n        <article class=\"card\">\n          <div class=\"ph\"><canvas data-hair=\"wave\" data-color=\"#8a5a3c\"></canvas></div>\n          <div class=\"body\">\n            <h3>客製髮片</h3>\n            <p>依頭型、稀疏面積與髮色訂製，適合大面積補髮或特殊需求。</p>\n            <div class=\"tags\"><span class=\"tag\">量身訂做</span><span class=\"tag\">約 3–4 週</span><span class=\"tag\">價格請洽詢</span></div>\n          </div>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"colors\" style=\"background:var(--surface);border-block:1px solid var(--line)\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\">\n        <p class=\"eyebrow\">髮色色票</p>\n        <h2>找到最接近你的髮色</h2>\n        <p>螢幕顯示會有色差，建議在自然光下拍一張髮根到髮尾的照片傳給我們，由我們幫你比色。<span class=\"note\">色號為示意</span></p>\n      </div>\n      <div class=\"swatches\">\n        <div class=\"sw\"><i style=\"background:#141011\"></i>自然黑<small>#1B</small></div>\n        <div class=\"sw\"><i style=\"background:#2a1d18\"></i>深棕黑<small>#2</small></div>\n        <div class=\"sw\"><i style=\"background:#3b2a22\"></i>自然深棕<small>#4</small></div>\n        <div class=\"sw\"><i style=\"background:#5a3b2a\"></i>巧克力棕<small>#6</small></div>\n        <div class=\"sw\"><i style=\"background:#7a4f35\"></i>栗子棕<small>#8</small></div>\n        <div class=\"sw\"><i style=\"background:#9a6a45\"></i>奶茶棕<small>#10</small></div>\n        <div class=\"sw\"><i style=\"background:#b88a5e\"></i>蜂蜜金棕<small>#12</small></div>\n        <div class=\"sw\"><i style=\"background:linear-gradient(135deg,#2a1d18 50%,#8e8a88 50%)\"></i>黑白混色<small>#2/51</small></div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"sizes\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\">\n        <p class=\"eyebrow\">尺寸挑選</p>\n        <h2>髮片底座要多大？</h2>\n        <p>用軟尺量出稀疏範圍的長和寬，各加 1–2 cm，就是適合的底座尺寸。</p>\n      </div>\n      <div class=\"tbl\">\n        <table>\n          <thead><tr><th>底座尺寸</th><th>適合範圍</th><th>建議髮長</th><th>適合對象</th></tr></thead>\n          <tbody>\n            <tr><td class=\"num\">6 × 9 cm</td><td>髮旋、分線處稀疏</td><td class=\"num\">25–35 cm</td><td>剛開始變薄、想遮分線</td></tr>\n            <tr><td class=\"num\">10 × 12 cm</td><td>頭頂中央稀疏</td><td class=\"num\">30–45 cm</td><td>最多人選擇的尺寸</td></tr>\n            <tr><td class=\"num\">13 × 15 cm</td><td>頭頂到前額大面積</td><td class=\"num\">35–50 cm</td><td>髮量明顯不足、想一次蓋滿</td></tr>\n            <tr><td class=\"num\">客製</td><td>依照片與測量訂做</td><td class=\"num\">依需求</td><td>特殊頭型、大面積補髮</td></tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"order\" style=\"background:var(--surface);border-block:1px solid var(--line)\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\">\n        <p class=\"eyebrow\">訂購流程</p>\n        <h2>四個步驟，在家就能完成</h2>\n      </div>\n      <ol class=\"steps\">\n        <li><h3>加 LINE 諮詢</h3><p>告訴我們想改善的地方，例如頭頂稀疏或想加長。</p></li>\n        <li><h3>拍照與測量</h3><p>傳頭頂照片與髮色照片，量出稀疏範圍的長寬。</p></li>\n        <li><h3>確認款式報價</h3><p>依尺寸、髮長、髮色推薦款式，確認後付款。</p></li>\n        <li><h3>出貨與配戴教學</h3><p>寄出髮片並附上配戴、清洗與保養說明。</p></li>\n      </ol>\n    </div>\n  </section>\n\n  <section id=\"faq\">\n    <div class=\"wrap\">\n      <div class=\"sec-head\">\n        <p class=\"eyebrow\">常見問題</p>\n        <h2>配戴前大家最常問的事</h2>\n      </div>\n      <div class=\"faq\">\n        <details open><summary>戴髮片會不會很明顯？</summary><p>選對髮色與底座尺寸，加上真人髮可以和原生髮一起整理，一般近距離也不容易看出來。</p></details>\n        <details><summary>真人髮可以燙、染、吹整嗎？</summary><p>可以。建議燙染交給熟悉髮片的設計師處理，日常吹整溫度不要超過 180°C。</p></details>\n        <details><summary>一頂髮片可以用多久？</summary><p>視配戴頻率與保養方式而定，正確清洗與收納通常可使用半年到一年以上。</p></details>\n        <details><summary>怎麼清洗和保養？</summary><p>約配戴 10–15 次清洗一次，用溫水和洗髮精輕洗，潤髮後自然陰乾，收在髮片網或盒子裡。</p></details>\n        <details><summary>可以退換貨嗎？</summary><p>未配戴、未修剪的商品可在到貨 7 天內聯繫我們辦理。客製商品恕不退換。<span class=\"note\">請依實際規定修改</span></p></details>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"contact\">\n    <div class=\"wrap\">\n      <div class=\"contact\">\n        <div>\n          <p class=\"eyebrow\">聯絡我們</p>\n          <h2>不確定適合哪一款？先聊聊</h2>\n          <p style=\"color:var(--muted);margin-top:10px\">加入官方 LINE，傳一張照片，我們會回覆建議的款式、尺寸與髮色。</p>\n          <div class=\"lineid\">\n            <code id=\"line-id\">@your-line-id</code>\n            <button class=\"btn ghost\" id=\"copy-btn\" type=\"button\">複製 LINE ID</button>\n            <a class=\"btn line\" href=\"https://line.me/R/ti/p/@your-line-id\">開啟 LINE</a>\n          </div>\n          <p class=\"toast\" id=\"toast\" role=\"status\"></p>\n        </div>\n        <dl class=\"info\">\n          <div><dt>營業時間</dt><dd style=\"margin:0\">週一至週六 10:00–20:00</dd></div>\n          <div><dt>服務方式</dt><dd style=\"margin:0\">線上諮詢、宅配到府</dd></div>\n          <div><dt>門市</dt><dd style=\"margin:0\">預約制（地址請提供）</dd></div>\n          <div><dt>社群</dt><dd style=\"margin:0\">Instagram / Facebook（請提供連結）</dd></div>\n        </dl>\n      </div>\n    </div>\n  </section>\n</main>\n\n<footer>\n  <div class=\"wrap\">© 2026 十八睞讓你美 ・ 真人髮片與補髮專門</div>\n</footer>\n\n<script>\n(function(){\n  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  function drawHair(cv, kind, color, t){\n    const r = cv.getBoundingClientRect();\n    const dpr = Math.min(devicePixelRatio||1, 2);\n    const w = Math.max(1, r.width), h = Math.max(1, r.height);\n    if (cv.width !== Math.round(w*dpr)) { cv.width = Math.round(w*dpr); cv.height = Math.round(h*dpr); }\n    const c = cv.getContext('2d');\n    c.setTransform(dpr,0,0,dpr,0,0);\n    c.clearRect(0,0,w,h);\n    const n = kind==='hero' ? 90 : 46;\n    let seed = 7;\n    const rnd = () => (seed = (seed*16807) % 2147483647) / 2147483647;\n    for (let i=0;i<n;i++){\n      const u = i/(n-1);\n      let x0, y0, len, amp, freq;\n      if (kind==='bang'){ x0 = w*(0.15+0.7*u); y0 = h*0.12; len = h*(0.45+0.1*rnd()); amp = 6; freq = 1.2; }\n      else if (kind==='top'){ x0 = w*(0.1+0.8*u); y0 = h*(0.18+0.08*Math.abs(u-.5)); len = h*0.75; amp = 10; freq = 1.4; }\n      else if (kind==='wave'){ x0 = w*(0.1+0.8*u); y0 = h*0.05; len = h*0.95; amp = 16; freq = 3; }\n      else { x0 = w*(0.08+0.84*u); y0 = h*0.02; len = h*1.05; amp = kind==='hero'?22:12; freq = kind==='hero'?1.8:1.6; }\n      const ph = rnd()*Math.PI*2;\n      c.beginPath();\n      for (let s=0;s<=40;s++){\n        const v = s/40;\n        const sway = Math.sin(v*freq*Math.PI + ph + t*0.0008) * amp * v;\n        const fall = (u-.5) * w * 0.15 * v;\n        const x = x0 + sway + fall, y = y0 + v*len;\n        s ? c.lineTo(x,y) : c.moveTo(x,y);\n      }\n      c.strokeStyle = color;\n      c.globalAlpha = 0.35 + 0.55*rnd();\n      c.lineWidth = 0.8 + rnd()*1.6;\n      c.stroke();\n    }\n    c.globalAlpha = 1;\n  }\n\n  const css = getComputedStyle(document.documentElement);\n  const hero = document.getElementById('hero-canvas');\n  const cards = [...document.querySelectorAll('canvas[data-hair]')];\n  function frame(t){\n    drawHair(hero, 'hero', css.getPropertyValue('--accent').trim() || '#8a2e4a', t);\n    if (!reduce) requestAnimationFrame(frame);\n  }\n  function drawCards(){ cards.forEach(cv => drawHair(cv, cv.dataset.hair, cv.dataset.color, 0)); }\n  frame(0); drawCards();\n  addEventListener('resize', () => { drawCards(); if (reduce) frame(0); });\n\n  const btn = document.getElementById('copy-btn'), toast = document.getElementById('toast');\n  btn.addEventListener('click', () => {\n    const id = document.getElementById('line-id').textContent;\n    navigator.clipboard.writeText(id).then(\n      () => { toast.textContent = '已複製 LINE ID：' + id; },\n      () => { const s = getSelection(), rg = document.createRange(); rg.selectNodeContents(document.getElementById('line-id')); s.removeAllRanges(); s.addRange(rg); toast.textContent = '已選取 LINE ID，請手動複製'; }\n    );\n  });\n})();\n</script>\n\n</body></html>\n";
